import json,numpy as np
m=json.load(open('/app/runs/pregrasp/meta.json'))['cameras']['egoview'];K=np.array(m['intrinsic_cv']);T=np.array(m['cam2world_gl']);
for name,w in [('target',[2.394,-1.874,1.204,1]),('can',[2.40,-1.86,1.05,1]),('can_mid',[2.40,-1.86,.99,1]),('drawer',[2.82,-1.84,.95,1])]:
 c=np.linalg.inv(T)@np.array(w); z=-c[2];u=K[0,0]*c[0]/z+K[0,2];v=K[1,1]*(-c[1])/z+K[1,2];print(name,'cam',c[:3], 'pixel',u,v)
PY

